await page.goto(baseUrl, { waitUntil: 'domcontentloaded' })
await page.waitForFunction(() => document.title === '登录' && document.body?.innerText.includes('用户登录'), null, { timeout: 15000 })
const cdpSession = await context.newCDPSession(page)
const authResult = await cdpSession.send('Runtime.evaluate', {
  expression: "uni.setStorageSync('flood-token-v1', 'visual-only-token'); uni.setStorageSync('flood-login-user-v1', JSON.stringify({ userId: 'visual-user', userName: 'visual-only', nickName: '截图校验' })); uni.reLaunch({ url: '/pages/home/index' }); 'ready'",
  awaitPromise: true,
  returnByValue: true,
})
await cdpSession.detach()
if (authResult.exceptionDetails) throw new Error(`DevTools token injection failed: ${authResult.exceptionDetails.text}`)

tool_input.new_string:
const captchaResponse = page.waitForResponse(response => new URL(response.url()).pathname.endsWith('/v2.0/code'), { timeout: 15000 }).catch(() => null)
await page.goto(baseUrl, { waitUntil: 'domcontentloaded' })
await page.waitForFunction(() => document.title === '登录' && document.body?.innerText.includes('用户登录'), null, { timeout: 15000 })
await captchaResponse
await page.getByPlaceholder('请输入用户名/身份证号码/手机号码').fill('visual-user')
await page.getByPlaceholder('请输入密码').fill('visual-password')
const agreement = page.locator('.login-agreement')
if (await agreement.getAttribute('aria-checked') !== 'true') await agreement.click()
const loginResponse = page.waitForResponse(response => new URL(response.url()).pathname.endsWith('/v2.0/security/auth/login'), { timeout: 15000 })
await page.locator('.login-submit').click()
const loginResult = await loginResponse
if (loginResult.status() !== 200) throw new Error(`Screenshot login fixture returned HTTP ${loginResult.status()}`)
